const lead = $("Edit Fields").first().json;
const input = $input.first().json;

const text = input.output[0].content[0].text;

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(`Failed to parse AI response as JSON: ${text}`);
}

return [
  {
    json: {
      ...lead,
      ...parsed,
    },
  },
];

const lead = $("Lead Data + AI Analysis").first().json;
const searchResult = $input.first().json;

const contactId = searchResult.results?.[0]?.id;

if (!contactId) {
  throw new Error("Expected existing HubSpot contact, but no contact ID was found.");
}

return [
  {
    json: {
      ...lead,
      hubspotContactId: contactId,
      hubspotContactExists: true,
    },
  },
];

