const lead = $("Lead Data + AI Analysis").first().json;
const createdContact = $input.first().json;

const contactId = createdContact.id;

if (!contactId) {
  throw new Error("HubSpot contact was created, but no contact ID was returned.");
}

return [
  {
    json: {
      ...lead,
      hubspotContactId: contactId,
      hubspotContactExists: false,
    },
  },
];

const lead = $input.first().json;

const clean = (value) =>
  String(value ?? "")
    .replace(/\r?\n/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const service = lead.service || lead.serviceInterestedIn;

const amount =
  lead.budgetRange === "$5-10K"
    ? "7500"
    : lead.budgetRange === "$10-20K"
      ? "15000"
      : lead.budgetRange === "$20-50K"
        ? "35000"
        : "50000";

return [
  {
    json: {
      hubspotContactId: lead.hubspotContactId,

      dealname: `${clean(lead.fullName)} — ${clean(service)}`,
      dealstage: "5030000846",
      amount,

      description: clean(
        `Service: ${service} | Budget: ${lead.budgetRange} | Project Details: ${lead.vision}`
      ),

      ai_fit_level: clean(lead.fitLevel),
      ai_followup_email_draft: clean(lead.followUpEmailDraft),
      ai_lead_score: Number(lead.leadScore),
      ai_summary: clean(lead.summary),
      ai_urgency: clean(lead.urgency),
      service_interested_in: clean(service),
      recommended_next_step: clean(lead.recommendedNextStep),
    },
  },
];
